CREATE TABLE "PublisherProfile" (
"id" TEXT PRIMARY KEY,"legalName" TEXT NOT NULL DEFAULT 'PT Bahasa Cerdas Indonesia',"imprintName" TEXT NOT NULL DEFAULT 'Bahasa Cerdas Indonesia',"directorName" TEXT NOT NULL DEFAULT '',"legalAddress" TEXT NOT NULL DEFAULT '',"correspondenceAddress" TEXT NOT NULL DEFAULT '',"email" TEXT NOT NULL DEFAULT '',"phone" TEXT NOT NULL DEFAULT '',"officialWebsite" TEXT NOT NULL DEFAULT '',"catalogWebsite" TEXT NOT NULL DEFAULT '',"nib" TEXT NOT NULL DEFAULT '',"kbI" TEXT NOT NULL DEFAULT '',"decreeNumber" TEXT NOT NULL DEFAULT '',"deedNumber" TEXT NOT NULL DEFAULT '',"perpusnasAccountStatus" TEXT NOT NULL DEFAULT 'NOT_REGISTERED',"perpusnasReference" TEXT NOT NULL DEFAULT '',"approvalNote" TEXT NOT NULL DEFAULT '',"updatedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL
);
CREATE TABLE "IsbnApplication" (
"id" TEXT PRIMARY KEY,"publisherId" TEXT NOT NULL DEFAULT 'bci-publisher',"bookId" TEXT NOT NULL,"createdById" TEXT NOT NULL,"title" TEXT NOT NULL,"subtitle" TEXT NOT NULL DEFAULT '',"authorNames" TEXT NOT NULL DEFAULT '',"language" TEXT NOT NULL DEFAULT 'id',"editionNumber" INTEGER NOT NULL DEFAULT 1,"format" TEXT NOT NULL DEFAULT 'PRINT',"binding" TEXT NOT NULL DEFAULT 'PAPERBACK',"paperSize" TEXT NOT NULL DEFAULT 'a5',"imprint" TEXT NOT NULL DEFAULT 'Bahasa Cerdas Indonesia',"plannedPublicationYear" INTEGER,"catalogUrl" TEXT NOT NULL DEFAULT '',"territory" TEXT NOT NULL DEFAULT 'GLOBAL',"rightsBasis" TEXT NOT NULL DEFAULT 'ORIGINAL',"originalWorkReference" TEXT NOT NULL DEFAULT '',"externalReference" TEXT NOT NULL DEFAULT '',"officialEvidenceUrl" TEXT NOT NULL DEFAULT '',"isbn13" TEXT UNIQUE,"kdtReference" TEXT NOT NULL DEFAULT '',"barcodeReference" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'DRAFT',"submittedAt" TIMESTAMP(3),"issuedAt" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"note" TEXT NOT NULL DEFAULT '',"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL
);
CREATE TABLE "IsbnDocument" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"uploaderId" TEXT NOT NULL,"kind" TEXT NOT NULL,"filename" TEXT NOT NULL,"mime" TEXT NOT NULL,"bytes" BYTEA NOT NULL,"size" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IsbnEvent" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"detail" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "IsbnApplication_bookId_createdAt_idx" ON "IsbnApplication"("bookId","createdAt");
CREATE INDEX "IsbnApplication_status_updatedAt_idx" ON "IsbnApplication"("status","updatedAt");
CREATE INDEX "IsbnDocument_applicationId_kind_createdAt_idx" ON "IsbnDocument"("applicationId","kind","createdAt");
CREATE INDEX "IsbnEvent_applicationId_createdAt_idx" ON "IsbnEvent"("applicationId","createdAt");
ALTER TABLE "IsbnApplication" ADD CONSTRAINT "IsbnApplication_publisherId_fkey" FOREIGN KEY("publisherId") REFERENCES "PublisherProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "IsbnApplication" ADD CONSTRAINT "IsbnApplication_bookId_fkey" FOREIGN KEY("bookId") REFERENCES "Book"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "IsbnDocument" ADD CONSTRAINT "IsbnDocument_applicationId_fkey" FOREIGN KEY("applicationId") REFERENCES "IsbnApplication"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IsbnDocument" ADD CONSTRAINT "IsbnDocument_uploaderId_fkey" FOREIGN KEY("uploaderId") REFERENCES "StudioUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "IsbnEvent" ADD CONSTRAINT "IsbnEvent_applicationId_fkey" FOREIGN KEY("applicationId") REFERENCES "IsbnApplication"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IsbnEvent" ADD CONSTRAINT "IsbnEvent_actorId_fkey" FOREIGN KEY("actorId") REFERENCES "StudioUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
